const renewLease = `-- name: RenewLease :execrows
UPDATE dispatches
SET updated_at       = ?1,
    lease_expires_at = CAST(?2 AS INTEGER),
    stop_acked_at    = CASE WHEN status = 'stopping' THEN coalesce(stop_acked_at, ?1) ELSE stop_acked_at END
WHERE id = ?3 AND epoch = ?4 AND status IN ('starting', 'running', 'stopping') AND lease_expires_at > ?1
`

type RenewLeaseParams struct {
	Now            int64
	LeaseExpiresAt int64
	ID             string
	Epoch          int64
}

// A lease that has run out is never renewed. The first heartbeat after a stop request acknowledges it.
func (q *Queries) RenewLease(ctx context.Context, arg RenewLeaseParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, renewLease,
		arg.Now,
		arg.LeaseExpiresAt,
		arg.ID,
		arg.Epoch,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

