const settleDispatch = `-- name: SettleDispatch :execrows
UPDATE dispatches
SET updated_at = ?1, status = ?2, failure_class = ?3, unknown_cause = NULL,
    result = ?4, resets_at = ?5, lease_expires_at = NULL, settled_at = ?1
WHERE id = ?6 AND status IN (/*SLICE:from_statuses*/?)
`

type SettleDispatchParams struct {
	Now          int64
	ToStatus     string
	FailureClass sql.NullString
	Result       sql.NullString
	ResetsAt     sql.NullInt64
	ID           string
	FromStatuses []string
}

func (q *Queries) SettleDispatch(ctx context.Context, arg SettleDispatchParams) (int64, error) {
	query := settleDispatch
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.ToStatus)
	queryParams = append(queryParams, arg.FailureClass)
	queryParams = append(queryParams, arg.Result)
	queryParams = append(queryParams, arg.ResetsAt)
	queryParams = append(queryParams, arg.ID)
	if len(arg.FromStatuses) > 0 {
		for _, v := range arg.FromStatuses {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", strings.Repeat(",?", len(arg.FromStatuses))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", "NULL", 1)
	}
	result, err := q.db.ExecContext(ctx, query, queryParams...)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

